const $=q=>document.querySelector(q);
let session=defaultSession(),tracks=new Map(DEMOS.map(t=>[t.id,structuredClone(t)])),ready=false,saveTimer,saveQueue=Promise.resolve(),storageFailed=false,audioStarting=null,routeApplied=false;
const engine=new AudioEngine(),jobs=new Map(),deckTokens=[0,0,0,0],midiTouch=[false,false,false,false],midiJogTimers=[null,null,null,null];let layout;
const api={get s(){return session;},get tracks(){return tracks;},get layout(){return layout;},engine,search:'',sort:{key:'addedAt',direction:-1},zoom:8,importing:false,jsonPurpose:'session',...storage,toast,modal,closeModal,save,snapshot,render,renderDeck,renderMixer,renderSampler,renderRows,getTrack,position,startAudio,applyAll,ensureBuffer,loadDeck,playDeck,seekDeck,cue,hotcue,loopDeck,resizeLoop,syncDeck,toggleDeck,updateTrack,importFiles,setSample,triggerSample,record,removeTrack,replaceValue,updateParamUI,restoreSession};
const controllers=api.controllers=new Controllers(()=>session,(...args)=>control(...args));
export {api};
function toast(message,error=false,duration=6500){const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),duration);}
function modal(title,body){$('#dialog-content').innerHTML=dialogFrame(title,body);if(!$('#dialog').open)$('#dialog').showModal();}
function closeModal(){$('#dialog').close();}
function snapshot(){const raw=structuredClone(session);raw.decks.forEach((d,i)=>{if(engine.loadedIds[i]===d.trackId)d.position=engine.positions[i];d.playing=false;});raw.savedAt=Date.now();return raw;}
function save(){if(!ready)return;$('#save-status').textContent='保存中…';clearTimeout(saveTimer);saveTimer=setTimeout(saveNow,650);}
async function saveNow(){if(!ready)return;const data=snapshot();saveQueue=saveQueue.catch(()=>{}).then(async()=>{try{await storage.putState(data);storageFailed=false;$('#save-status').textContent='✓ 保存済み';try{localStorage.setItem('orbit-session-recovery',JSON.stringify(data));}catch{}}catch(e){$('#save-status').textContent='保存できません';if(!storageFailed)toast('端末への保存に失敗しました。設定からセッションJSONを書き出してください。容量不足やプライベートモードを確認してください。',true,12000);storageFailed=true;}});return saveQueue;}
function getTrack(i){return tracks.get(session.decks[i].trackId);}
function position(i){return engine.loadedIds[i]===session.decks[i].trackId?engine.positions[i]:session.decks[i].position;}
function render(){const s=session;$('#workspace').innerHTML=panel('waves',wavesMarkup(s),`<label class="wave-style"><select data-waveform-style aria-label="波形の配色">${[['rgb','RGB'],['3band','3 BAND'],['deck','DECK']].map(([v,label])=>`<option value="${v}" ${s.waveformStyle===v?'selected':''}>${label}</option>`).join('')}</select></label><span class="wave-color-key" data-wave-colors="${s.waveformStyle}"><i>低</i><i>中</i><i>高</i></span><button data-action="zoom-out" aria-label="波形を縮小">−</button><span class="wave-zoom mono" id="wave-zoom">${api.zoom}s</span><button data-action="zoom-in" aria-label="波形を拡大">＋</button>`)+s.decks.map((d,i)=>panel(`deck${i}`,deckMarkup(i,s,getTrack(i)))).join('')+panel('mixer',mixerMarkup(s),'<button data-action="settings">OUTPUT ↗</button>')+panel('library',libraryMarkup(s,tracks),`<span class="muted mono">${tracks.size} TRACKS</span>`)+panel('sampler',samplerMarkup(s,tracks));renderRows();layout?.apply();document.querySelectorAll('[data-preset]').forEach(el=>el.classList.toggle('active',el.dataset.preset===s.preset));}
function renderDeck(i){const host=$(`[data-panel="deck${i}"] .panel-body`);if(host)host.innerHTML=deckMarkup(i,session,getTrack(i));layout?.apply();}
function renderMixer(){const host=$('[data-panel=mixer] .panel-body');if(host)host.innerHTML=mixerMarkup(session);}
function renderSampler(){const host=$('[data-panel=sampler] .panel-body');if(host)host.innerHTML=samplerMarkup(session,tracks);}
function renderRows(){let list=[...tracks.values()],p=session.playlist;if(p==='favorites')list=list.filter(t=>t.rating>0);else if(p==='history'){const ids=new Set(session.history.map(h=>h.trackId));list=list.filter(t=>ids.has(t.id));}else if(p!=='all'){const ids=new Set(session.playlists.find(x=>x.id===p)?.tracks||[]);list=list.filter(t=>ids.has(t.id));}const q=api.search.trim().toLocaleLowerCase();if(q)list=list.filter(t=>[t.name,t.artist,t.bpm,t.key,t.comment].join(' ').toLocaleLowerCase().includes(q));list.sort((a,b)=>{const x=a[api.sort.key]??'',y=b[api.sort.key]??'';return api.sort.direction*(typeof x==='number'&&typeof y==='number'?x-y:String(x).localeCompare(String(y),'ja'));});if($('#track-rows'))$('#track-rows').innerHTML=trackRows(list,session);if($('#track-count'))$('#track-count').textContent=`${list.length} 曲 · ${time(list.reduce((n,t)=>n+t.duration,0))}`;if($('#track-search')&&$('#track-search').value!==api.search)$('#track-search').value=api.search;}
async function startAudio(){if(audioStarting)return audioStarting;audioStarting=(async()=>{await engine.init();applyAll();if(!routeApplied){try{await engine.setRoute(session.mixer);}catch(e){toast('音声出力を復元できません：'+e.message,true);session.mixer.route='stereo';session.mixer.masterSink='default';session.mixer.cueSink='default';await engine.setRoute(session.mixer);save();}routeApplied=true;}$('#audio-start').textContent='AUDIO ON';$('#audio-start').classList.add('active');})();try{await audioStarting;}finally{audioStarting=null;}}
function applyAll(){session.decks.forEach((d,i)=>engine.applyDeck(i,d,getTrack(i)?.bpm));engine.applyMixer(session.mixer,session.decks);}
async function ensureBuffer(id){if(!id)throw new Error('音源をロードしてください。');if(engine.has(id))return;if(jobs.has(id))return await jobs.get(id);const job=(async()=>{const t=tracks.get(id);if(!t)throw new Error('音源がライブラリにありません。');await startAudio();let blob=await storage.getAudio(id);if(!blob&&t.demo){const r=await fetch(new URL(t.source,import.meta.url));if(!r.ok)throw new Error('デモ音源を読み込めません。接続を確認してください。');blob=await r.blob();}if(!blob)throw new Error('音源ファイルがありません。同じファイルを再登録してください。');const decoded=await engine.decode(blob);if(!t.waveform){try{Object.assign(t,await waveform(decoded));await storage.putTrack(t);}catch(e){toast('カラー波形を更新できませんでした。音源は再生できます。',true);}}await engine.addBuffer(id,decoded,session.sampler.filter(Boolean).map(p=>p.trackId));})();jobs.set(id,job);try{await job;}finally{jobs.delete(id);}}
async function loadDeck(i,id,force=false){const d=session.decks[i],t=tracks.get(id);if(!t)throw new Error('音源がありません。');if(d.locked&&!force)throw new Error(`DECK ${LETTERS[i]}をOPENに切り替えてください。`);if(d.playing&&!force)throw new Error(`DECK ${LETTERS[i]}を停止してからロードしてください。`);const token=++deckTokens[i];await ensureBuffer(id);if(token!==deckTokens[i])return;d.trackId=id;d.position=0;d.cuePoint=t.cues?.[0]??0;d.playing=false;d.loop={enabled:false,start:0,end:0};d.reverse=false;engine.load(i,id);engine.applyDeck(i,d,t.bpm);engine.applyMixer(session.mixer,session.decks);renderDeck(i);save();toast(`${t.name} → DECK ${LETTERS[i]}`,false,1800);}
async function playDeck(i,on){const d=session.decks[i];if(!d.trackId)throw new Error('ライブラリから音源をロードしてください。');const desired=on??!d.playing,request=++deckTokens[i];if(desired){await startAudio();await ensureBuffer(d.trackId);if(request!==deckTokens[i])return;if(engine.loadedIds[i]!==d.trackId){engine.load(i,d.trackId,d.position);engine.applyDeck(i,d,getTrack(i)?.bpm);}if(engine.positions[i]>=(getTrack(i)?.duration||0)-.02){engine.seek(i,0);d.position=0;}session.history.push({trackId:d.trackId,at:Date.now(),deck:i});session.history=session.history.slice(-500);}d.playing=desired;engine.play(i,desired);if(!desired)d.position=position(i);renderDeck(i);controllers.feedback(`deck.${i}.play`,desired);save();}
function seekDeck(i,pos){const t=getTrack(i);if(!t)return;const p=clamp(pos,0,Math.max(0,t.duration-.001));session.decks[i].position=p;if(engine.loadedIds[i]===t.id)engine.seek(i,p);save();}
async function cue(i){const d=session.decks[i],t=getTrack(i);if(!t)return;if(d.playing){await playDeck(i,false);seekDeck(i,d.cuePoint);}else{d.cuePoint=d.quantize?quantize(position(i),t.bpm,t.gridOffset):position(i);seekDeck(i,d.cuePoint);toast(`DECK ${LETTERS[i]} CUE ${time(d.cuePoint)}`,false,1800);save();}}
async function hotcue(i,j,remove=false){const t=getTrack(i);if(!t)return;const d=session.decks[i];t.cues||=Array(8).fill(null);if(remove){t.cues[j]=null;await updateTrack(t);}else if(t.cues[j]==null){t.cues[j]=clamp(d.quantize?quantize(position(i),t.bpm,t.gridOffset):position(i),0,t.duration);await updateTrack(t);}else{await ensureBuffer(d.trackId);if(engine.loadedIds[i]!==d.trackId){engine.load(i,d.trackId,d.position);engine.applyDeck(i,d,t.bpm);}seekDeck(i,t.cues[j]);if(!d.playing)await playDeck(i,true);}renderDeck(i);controllers.feedback(`deck.${i}.hotcue${j}`,t.cues[j]!=null);save();}
function loopDeck(i){const d=session.decks[i],t=getTrack(i);if(!t)return;if(d.loop.enabled)d.loop.enabled=false;else{const start=clamp(d.quantize?quantize(position(i),t.bpm,t.gridOffset):position(i),0,t.duration-.02);d.loop={enabled:true,start,end:Math.min(t.duration,start+d.loopBeats*60/t.bpm)};if(d.loop.enabled)seekDeck(i,start);}engine.applyDeck(i,d,t.bpm);renderDeck(i);save();}
function resizeLoop(i,mult){const d=session.decks[i],t=getTrack(i);d.loopBeats=clamp(d.loopBeats*mult,.125,128);if(d.loop.enabled&&t)d.loop.end=Math.min(t.duration,d.loop.start+d.loopBeats*60/t.bpm);engine.applyDeck(i,d,t?.bpm);renderDeck(i);save();}
async function syncDeck(i){const m=session.selectedDeck;if(i===m){toast('同期先のデッキでSYNCを押してください。MASTERを基準に合わせます。');return;}const d=session.decks[i],t=getTrack(i),mt=getTrack(m);if(!t||!mt)throw new Error('両方のデッキに音源をロードしてください。');await ensureBuffer(d.trackId);if(engine.loadedIds[i]!==d.trackId)engine.load(i,d.trackId,d.position);d.rate=clamp(mt.bpm*session.decks[m].rate/t.bpm,.5,1.5);seekDeck(i,alignedPosition(position(i),t.bpm,t.gridOffset,position(m),mt.bpm,mt.gridOffset));engine.applyDeck(i,d,t.bpm);renderDeck(i);save();}
function toggleDeck(i,key){if(!['keyLock','reverse','slip','quantize','cueOn'].includes(key))return;const d=session.decks[i];d[key]=!d[key];engine.applyDeck(i,d,getTrack(i)?.bpm);renderDeck(i);if(key==='cueOn'){renderMixer();if(d.cueOn&&session.mixer.route==='stereo')toast('CUEを有効にしました。聴くには設定でCUE出力を選んでください。');}controllers.feedback(`deck.${i}.${key}`,d[key]);save();}
async function updateTrack(t){tracks.set(t.id,t);try{await storage.putTrack(t);}catch(e){toast('曲情報を保存できませんでした。セッションを書き出してください。',true);throw e;}session.decks.forEach((d,i)=>{if(d.trackId===t.id){engine.applyDeck(i,d,t.bpm);renderDeck(i);}});renderRows();save();}
async function importFiles(files){if(api.importing){toast('音源の取り込みが終わるまでお待ちください。');return;}const supported=Array.from(files).filter(f=>f.type.startsWith('audio/')||/\.(wav|mp3|flac|aiff?|m4a|ogg|opus|aac|webm|mp4)$/i.test(f.name));if(!supported.length)throw new Error('音声ファイルを選んでください。');api.importing=true;let ok=0;const failures=[];try{await startAudio();for(let index=0;index<supported.length;index++){const f=supported[index];$('#storage-status').textContent=`取り込み ${index+1}/${supported.length} · ${f.name}`;try{if(f.size>300*1024*1024)throw new Error('1ファイル300 MBを超えています。');const exists=[...tracks.values()].find(t=>!t.demo&&t.filename===f.name&&t.size===f.size);if(exists){await storage.storeTrack({...exists,missing:false},f);exists.missing=false;ok++;continue;}const decoded=await engine.decode(f);if(decoded.duration>3600||decoded.length*decoded.numberOfChannels*4>engine.maxBytes)throw new Error('1時間またはデコード512 MBを超える音源です。');const wave=await waveform(decoded);let result;try{result=await analyse(decoded);}catch{result={bpm:120,bpmConfidence:0,key:'—',keyConfidence:0,gridOffset:0};toast(`${f.name}：BPMを手入力してください。`,true);}const id=crypto.randomUUID(),name=f.name.replace(/\.[^.]+$/,''),parts=name.split(' - ');const t=normalizeTrack({id,name:parts.length>1?parts.slice(1).join(' - '):name,artist:parts.length>1?parts[0]:'',filename:f.name,size:f.size,duration:decoded.duration,sampleRate:decoded.sampleRate,addedAt:Date.now(),...wave,...result,cues:Array(8).fill(null),rating:0,comment:''});await storage.storeTrack(t,f);tracks.set(id,t);if(!ok)session.selectedTrack=id;ok++;renderRows();}catch(e){failures.push(`${f.name}: ${e.message}`);}}render();save();toast(`${ok}曲をこの端末に保存しました。`,false,6000);if(failures.length)modal('取り込み結果',`<p>${ok}曲を保存しました。</p><ul>${failures.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`);}finally{api.importing=false;$('#storage-status').textContent='音源はこの端末内で処理';}}
async function setSample(i,p){if(p)await ensureBuffer(p.trackId);session.sampler[i]=p;renderSampler();save();}
async function triggerSample(i){const p=session.sampler[i];if(!p){showSampleEditor(api,i);return;}await ensureBuffer(p.trackId);engine.sample(i,p);}
async function record(){await startAudio();if(engine.recording){$('#record-button').classList.remove('is-recording');const blob=await engine.stopRecording();if(!blob)return;const ext=blob.type.includes('mp4')?'m4a':blob.type.includes('ogg')?'ogg':'webm',name=`SeekDeck-Mix-${new Date().toISOString().replace(/[:.]/g,'-')}.${ext}`;storage.downloadBlob(blob,name);try{const a=await engine.decode(blob),t=normalizeTrack({id:crypto.randomUUID(),name:name.replace(/\.[^.]+$/,''),filename:name,artist:'SeekDeck · RECORDING',duration:a.duration,size:blob.size,bpm:getTrack(session.selectedDeck)?.bpm||120,bpmConfidence:0,key:'—',addedAt:Date.now(),...(await waveform(a)),cues:Array(8).fill(null)});await storage.storeTrack(t,blob);tracks.set(t.id,t);render();save();toast('ミックスをダウンロードし、ライブラリにも保存しました。');}catch(e){toast('録音をダウンロードしました。ライブラリへの追加はできませんでした：'+e.message,true);}}else{engine.startRecording();$('#record-button').classList.add('is-recording');toast('MASTER出力の録音を開始しました。RECをもう一度押すと保存します。');}}
async function removeTrack(id){const t=tracks.get(id);if(!t)return;if(t.demo)throw new Error('デモ音源は削除できません。クレートで表示を分けられます。');if(session.decks.some(d=>d.trackId===id&&d.playing))throw new Error('再生中の音源は削除できません。');await storage.deleteTrack(id);tracks.delete(id);session.decks.forEach((d,i)=>{if(d.trackId===id){d.trackId=null;d.position=0;engine.load(i,null);}});session.playlists.forEach(p=>p.tracks=p.tracks.filter(x=>x!==id));session.sampler=session.sampler.map(p=>p?.trackId===id?null:p);engine.stopSamples();render();save();}
function replaceValue(i,key,value){const d=session.decks[i],bounds={rate:[.5,1.5],pitch:[-12,12],volume:[0,1],gain:[-24,12],low:[-30,12],mid:[-30,12],high:[-30,12],filter:[-1,1],'fx.mix':[0,1],'fx.beats':[.125,4]};if(bounds[key])value=clamp(value,...bounds[key]);if(key==='pitch')value=Math.round(value);if(key.startsWith('fx.'))d.fx[key.slice(3)]=key==='fx.type'?value:Number(value);else d[key]=key==='assign'?value:Number(value);engine.applyDeck(i,d,getTrack(i)?.bpm);engine.applyMixer(session.mixer,session.decks);save();}
function updateParamUI(i,key,value){const input=$(`[data-deck="${i}"][data-param="${key}"]`);if(input&&document.activeElement!==input)input.value=value;const out=$(`[data-value="deck.${i}.${key}"]`);if(out)out.textContent=key==='rate'?`${((value-1)*100).toFixed(2)}%`:Number(value).toFixed(key==='filter'?2:1);const knob=input?.closest('.knob');if(knob)knob.style.setProperty('--angle',`${(value-Number(input.min))/(Number(input.max)-Number(input.min))*270-135}deg`);}
async function control(target,value,meta={}){try{const parts=target.split('.'),trigger=meta.pressed??value>0;if(parts[0]==='mixer'){const k=parts[1],v=k==='crossfader'?value*2-1:value;session.mixer[k]=meta.relative?clamp(session.mixer[k]+value*.01,k==='crossfader'?-1:0,1):v;engine.applyMixer(session.mixer,session.decks);const input=$(`[data-mixer="${k}"]`);if(input)input.value=session.mixer[k];save();return;}if(parts[0]==='sampler'){if(trigger)await triggerSample(Number(parts[1]));return;}const i=Number(parts[1]),key=parts[2],d=session.decks[i];if(!d)return;if(key.startsWith('hotcue')){if(trigger)await hotcue(i,Number(key.slice(6)));return;}if(key==='jog'){if(meta.relative){clearTimeout(midiJogTimers[i]);if(midiTouch[i]){engine.scratch(i,true,clamp(value*.35,-8,8));midiJogTimers[i]=setTimeout(()=>{if(midiTouch[i])engine.scratch(i,true,0);},80);}else if(d.playing){engine.applyDeck(i,{...d,rate:d.rate*(1+clamp(value*.015,-.2,.2))},getTrack(i)?.bpm);midiJogTimers[i]=setTimeout(()=>engine.applyDeck(i,session.decks[i],getTrack(i)?.bpm),90);}else seekDeck(i,position(i)+value*.03);}else seekDeck(i,value*(getTrack(i)?.duration||0));return;}if(key==='scratch'){midiTouch[i]=value>0;engine.scratch(i,midiTouch[i],0);return;}if(['play','cue','sync','loop','reverse','slip','keyLock','cueOn'].includes(key)){if(!trigger)return;if(key==='play')await playDeck(i);else if(key==='cue')await cue(i);else if(key==='sync')await syncDeck(i);else if(key==='loop')loopDeck(i);else toggleDeck(i,key);return;}const bounds={rate:[.5,1.5],pitch:[-12,12],volume:[0,1],gain:[-24,12],low:[-30,12],mid:[-30,12],high:[-30,12],filter:[-1,1],fx:[0,1]},b=bounds[key];if(!b)return;const actual=key==='fx'?'fx.mix':key,old=key==='fx'?d.fx.mix:d[key],v=meta.relative?clamp(old+value*(b[1]-b[0])*.005,...b):b[0]+value*(b[1]-b[0]);replaceValue(i,actual,key==='pitch'?Math.round(v):v);updateParamUI(i,actual,v);}catch(e){toast(e.message,true);}}
async function restoreSession(raw){if(engine.recording)throw new Error('録音を停止してからセッションを読み込んでください。');const next=normalizeSession(raw.session||raw);for(let i=0;i<4;i++)deckTokens[i]++;engine.stopSamples();session.decks.forEach((_,i)=>engine.play(i,false));if(Array.isArray(raw.tracks))for(const t of raw.tracks){if(!t||typeof t.id!=='string')continue;const existing=tracks.get(t.id);if(existing){const updated=normalizeTrack({...existing,...t,source:existing.source,demo:existing.demo,missing:existing.missing});tracks.set(t.id,updated);await storage.putTrack(updated);}else if(!t.demo){const restored=normalizeTrack({...t,missing:!(await storage.getAudio(t.id))});tracks.set(t.id,restored);await storage.putTrack(restored);}}session=next;session.decks.forEach((d,i)=>{if(!tracks.has(d.trackId))d.trackId=null;engine.load(i,null,0);});routeApplied=false;applyAll();render();layout.tools();save();toast('セッションを復元しました。音源・出力を確認してから再生してください。');}
engine.addEventListener('ended',e=>{const i=e.detail;session.decks[i].playing=false;session.decks[i].position=engine.positions[i];renderDeck(i);save();});engine.addEventListener('error',e=>toast(e.detail,true));engine.addEventListener('state',e=>{$('#engine-status').textContent=e.detail==='running'?`AUDIOWORKLET · ${Math.round(engine.context.sampleRate/1000)} kHz`:'AUDIO '+e.detail.toUpperCase();if(e.detail!=='running')$('#audio-start').textContent='オーディオ再開';});
window.addEventListener('pagehide',()=>{try{localStorage.setItem('orbit-session-recovery',JSON.stringify(snapshot()));}catch{}saveNow();});window.addEventListener('beforeunload',e=>{if(engine.recording||api.importing){e.preventDefault();e.returnValue='';}});
async function boot(){try{const [saved,stored]=await Promise.all([storage.getState(),storage.getTracks()]);stored.forEach(t=>{try{tracks.set(t.id,normalizeTrack(t));}catch{}});let raw=saved;try{const recovery=JSON.parse(localStorage.getItem('orbit-session-recovery')||'null');if(recovery?.savedAt>(saved?.savedAt||0))raw=recovery;}catch{}if(raw)try{session=normalizeSession(raw);}catch{toast('保存された設定を読み込めません。初期配置で開始します。',true);}session.decks.forEach(d=>{if(d.trackId&&!tracks.has(d.trackId)){d.trackId=null;d.position=0;}});}catch{toast('端末ストレージを開けません。今回の変更は保存されません。',true,12000);storageFailed=true;}ready=true;render();layout=new LayoutManager($('#workspace'),()=>session,save,toast);layout.apply();$('#save-status').textContent=storageFailed?'保存不可':'✓ 保存済み';attachEvents(api);startVisuals(api);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});registerTools(api);}
boot().catch(e=>toast('起動に失敗しました：'+e.message,true,20000));
